  enrolled_at timestamp with time zone DEFAULT now(),
  CONSTRAINT acc_course_enrollments_pkey PRIMARY KEY (id),
  CONSTRAINT acc_course_enrollments_user_email_course_id_key UNIQUE (user_email, course_id)
);

