-- ── equipment_inventory ───────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.equipment_inventory (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  name text NOT NULL,
  equipment_type text NOT NULL,
  brand text,
  model text,
  serial_number text,
  purchase_date date,
  last_calibration date,
  next_calibration_due date,
  status text DEFAULT 'available'::text,
  current_job_id uuid,
  notes text,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  next_available_at timestamp with time zone,
  current_reservation_id uuid,
  item_kind text,
  category text,
  current_status text,
  qr_code_id text,
  acquired_at timestamp with time zone,
  acquired_cost_cents bigint,
  useful_life_months integer,
  placed_in_service_at date,
  last_calibrated_at timestamp with time zone,
  next_calibration_due_at timestamp with time zone,
  warranty_expires_at timestamp with time zone,
  service_contract_vendor text,
  last_serviced_at timestamp with time zone,
  unit text,
  quantity_on_hand integer,
  low_stock_threshold integer,
  last_restocked_at timestamp with time zone,
  vendor text,
  cost_per_unit_cents integer,
  home_location text,
  vehicle_id uuid,
  is_personal boolean DEFAULT false NOT NULL,
  owner_user_id uuid,
  retired_at timestamp with time zone,
  retired_reason text,
  serial_suspect boolean DEFAULT false NOT NULL,
  photo_url text,
  condition text,
  condition_updated_at timestamp with time zone,
  linked_acquisition_receipt_id uuid,
  depreciation_method text DEFAULT 'straight_line'::text NOT NULL,
  disposed_at date,
  disposal_proceeds_cents bigint,
  disposal_kind text,
  tax_year_locked_through integer,
  CONSTRAINT equipment_inventory_condition_chk CHECK (((condition IS NULL) OR (condition = ANY (ARRAY['new'::text, 'good'::text, 'fair'::text, 'poor'::text, 'damaged'::text, 'needs_repair'::text])))),
  CONSTRAINT equipment_inventory_current_status_chk CHECK (((current_status IS NULL) OR (current_status = ANY (ARRAY['available'::text, 'in_use'::text, 'maintenance'::text, 'loaned_out'::text, 'lost'::text, 'retired'::text])))),
  CONSTRAINT equipment_inventory_depreciation_method_chk CHECK ((depreciation_method = ANY (ARRAY['section_179'::text, 'straight_line'::text, 'macrs_5yr'::text, 'macrs_7yr'::text, 'bonus_first_year'::text, 'none'::text]))),
  CONSTRAINT equipment_inventory_disposal_kind_chk CHECK (((disposal_kind IS NULL) OR (disposal_kind = ANY (ARRAY['sold'::text, 'traded'::text, 'scrapped'::text, 'lost'::text, 'stolen'::text, 'donated'::text])))),
  CONSTRAINT equipment_inventory_item_kind_chk CHECK (((item_kind IS NULL) OR (item_kind = ANY (ARRAY['durable'::text, 'consumable'::text, 'kit'::text])))),
  CONSTRAINT equipment_inventory_pkey PRIMARY KEY (id),
  CONSTRAINT equipment_inventory_qr_code_id_unique UNIQUE (qr_code_id)
);

