  id uuid DEFAULT gen_random_uuid() NOT NULL,
  job_id uuid NOT NULL,
  from_stage text,
  to_stage text NOT NULL,
  changed_by text NOT NULL,
  notes text,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT job_stages_history_pkey PRIMARY KEY (id)
);

-- ── job_tags ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.job_tags (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  job_id uuid NOT NULL,
  tag text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  org_id uuid NOT NULL,
  CONSTRAINT job_tags_pkey PRIMARY KEY (id)
);

-- ── job_team ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.job_team (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  job_id uuid NOT NULL,
  user_email text NOT NULL,
  user_name text,
  role text NOT NULL,
  assigned_at timestamp with time zone DEFAULT now(),
  removed_at timestamp with time zone,
  notes text,
  org_id uuid NOT NULL,
  assigned_from timestamp with time zone,
  assigned_to timestamp with time zone,
  slot_role text,
  state text,
  confirmed_at timestamp with time zone,
  declined_at timestamp with time zone,
  decline_reason text,
  is_crew_lead boolean DEFAULT false NOT NULL,
  is_override boolean DEFAULT false NOT NULL,
  override_reason text,
  CONSTRAINT job_team_override_requires_reason_chk CHECK (((is_override = false) OR ((override_reason IS NOT NULL) AND (length(TRIM(BOTH FROM override_reason)) > 0)))),
  CONSTRAINT job_team_state_chk CHECK (((state IS NULL) OR (state = ANY (ARRAY['proposed'::text, 'confirmed'::text, 'declined'::text, 'cancelled'::text])))),
  CONSTRAINT job_team_window_chk CHECK (((assigned_from IS NULL) OR (assigned_to IS NULL) OR (assigned_to > assigned_from))),
  CONSTRAINT job_team_pkey PRIMARY KEY (id)
);

-- ── job_time_entries ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.job_time_entries (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  job_id uuid NOT NULL,
  user_email text NOT NULL,
  user_name text,
  work_type text DEFAULT 'general'::text,
  start_time timestamp with time zone NOT NULL,
  end_time timestamp with time zone,
  duration_minutes integer,
  description text,
  billable boolean DEFAULT true,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT job_time_entries_pkey PRIMARY KEY (id)
);

-- ── jobs ──────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.jobs (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  job_number text NOT NULL,
  name text NOT NULL,
  description text,
  address text,
  city text,
  state text DEFAULT 'TX'::text,
  zip text,
  county text,
  latitude numeric(10,7),
  longitude numeric(10,7),
  survey_type text DEFAULT 'boundary'::text NOT NULL,
  acreage numeric(12,4),
  lot_number text,
  subdivision text,
  abstract_number text,
  stage text DEFAULT 'quote'::text NOT NULL,
  stage_changed_at timestamp with time zone DEFAULT now(),
  date_received timestamp with time zone DEFAULT now(),
  date_quoted timestamp with time zone,
  date_accepted timestamp with time zone,
  date_started timestamp with time zone,
  date_fieldwork_complete timestamp with time zone,
  date_drawing_complete timestamp with time zone,
  date_legal_complete timestamp with time zone,
  date_delivered timestamp with time zone,
  deadline timestamp with time zone,
  quote_amount numeric(12,2),
  final_amount numeric(12,2),
  amount_paid numeric(12,2) DEFAULT 0,
  payment_status text DEFAULT 'unpaid'::text,
  payment_notes text,
  client_name text,
  client_email text,
  client_phone text,
  client_company text,
  client_address text,
  lead_rpls_email text,
  conversation_id uuid,
  is_priority boolean DEFAULT false,
  is_archived boolean DEFAULT false,
  is_legacy boolean DEFAULT false,
  notes text,
  created_by text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  org_id uuid NOT NULL,
  result text,
  result_set_at timestamp with time zone,
  result_reason text,
  deliverables text,
  deleted_at timestamp with time zone,
  instructions text,
  CONSTRAINT jobs_result_check CHECK (((result IS NULL) OR (result = ANY (ARRAY['won'::text, 'lost'::text, 'abandoned'::text])))),
  CONSTRAINT jobs_pkey PRIMARY KEY (id),
  CONSTRAINT jobs_job_number_key UNIQUE (job_number)
);

-- ── learning_assignments ──────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.learning_assignments (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  assigned_to text NOT NULL,
  assigned_by text NOT NULL,
  module_id uuid,
  lesson_id uuid,
  unlock_next boolean DEFAULT false,
  status text DEFAULT 'pending'::text NOT NULL,
  due_date timestamp with time zone,
  completed_at timestamp with time zone,
  notes text,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  CONSTRAINT learning_assignments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text]))),
  CONSTRAINT learning_assignments_pkey PRIMARY KEY (id)
);

-- ── learning_credit_values ────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.learning_credit_values (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  entity_type text NOT NULL,
  entity_id uuid,
  entity_label text,
  credit_points integer DEFAULT 0 NOT NULL,
  description text,
  is_active boolean DEFAULT true,
  created_by text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  CONSTRAINT learning_credit_values_credit_points_check CHECK ((credit_points >= 0)),
  CONSTRAINT learning_credit_values_entity_type_check CHECK ((entity_type = ANY (ARRAY['module'::text, 'lesson'::text, 'quiz_pass'::text, 'exam_prep_pass'::text, 'flashcard_mastery'::text]))),
  CONSTRAINT learning_credit_values_pkey PRIMARY KEY (id)
);

-- ── learning_lessons ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.learning_lessons (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  module_id uuid NOT NULL,
  title text NOT NULL,
  content text,
  key_takeaways text[] DEFAULT '{}'::text[],
  order_index integer DEFAULT 0 NOT NULL,
  estimated_minutes integer DEFAULT 15,
  resources jsonb DEFAULT '[]'::jsonb,
  videos jsonb DEFAULT '[]'::jsonb,
  tags text[] DEFAULT '{}'::text[],
  status text DEFAULT 'draft'::text,
  xp_reward integer DEFAULT 50,
  deleted_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  difficulty_level text DEFAULT 'beginner'::text,
  version integer DEFAULT 1,
  is_published boolean DEFAULT true,
  review_status text DEFAULT 'approved'::text,
  content_format text DEFAULT 'rich_text'::text,
  prerequisite_lesson_id uuid,
  description text,
  learning_objectives text[] DEFAULT '{}'::text[],
  content_migrated boolean DEFAULT false,
  CONSTRAINT learning_lessons_content_format_check CHECK ((content_format = ANY (ARRAY['rich_text'::text, 'markdown'::text, 'video'::text, 'interactive'::text, 'mixed'::text]))),
  CONSTRAINT learning_lessons_difficulty_level_check CHECK ((difficulty_level = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text, 'expert'::text]))),
  CONSTRAINT learning_lessons_review_status_check CHECK ((review_status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'approved'::text, 'needs_revision'::text]))),
  CONSTRAINT learning_lessons_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text]))),
  CONSTRAINT learning_lessons_pkey PRIMARY KEY (id)
);

-- ── learning_modules ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.learning_modules (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  title text NOT NULL,
  description text,
  difficulty text DEFAULT 'beginner'::text,
  estimated_hours numeric(4,1) DEFAULT 1.0,
  order_index integer DEFAULT 0 NOT NULL,
  status text DEFAULT 'draft'::text,
  tags text[] DEFAULT '{}'::text[],
  xp_reward integer DEFAULT 200,
  is_fs_required boolean DEFAULT false,
  deleted_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  difficulty_level text DEFAULT 'beginner'::text,
  estimated_minutes integer DEFAULT 60,
  version integer DEFAULT 1,
  is_published boolean DEFAULT true,
  published_at timestamp with time zone,
  review_status text DEFAULT 'approved'::text,
  last_reviewed_by text,
  last_reviewed_at timestamp with time zone,
  acc_course_id text,
  is_academic boolean DEFAULT false,
  credential_key text,
  CONSTRAINT learning_modules_difficulty_check CHECK ((difficulty = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text]))),
  CONSTRAINT learning_modules_difficulty_level_check CHECK ((difficulty_level = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text, 'expert'::text]))),
  CONSTRAINT learning_modules_review_status_check CHECK ((review_status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'approved'::text, 'needs_revision'::text]))),
  CONSTRAINT learning_modules_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text]))),
  CONSTRAINT learning_modules_pkey PRIMARY KEY (id)
);

-- ── learning_topics ───────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.learning_topics (
