  paid_at timestamp with time zone,
  notes text,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT pay_advance_requests_amount_check CHECK ((amount > (0)::numeric)),
  CONSTRAINT pay_advance_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'denied'::text, 'paid'::text, 'cancelled'::text]))),
  CONSTRAINT pay_advance_requests_pkey PRIMARY KEY (id)
);

