);

-- ── payout_log ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.payout_log (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  user_email text NOT NULL,
  payout_type text NOT NULL,
  amount numeric(10,2) NOT NULL,
  reason text NOT NULL,
  details text,
  old_rate numeric(10,2),
  new_rate numeric(10,2),
  old_role text,
  new_role text,
  source_type text,
  source_id uuid,
  processed_by text,
  processed_at timestamp with time zone DEFAULT now(),
  pay_period_start date,
  pay_period_end date,
  status text DEFAULT 'completed'::text,
  created_at timestamp with time zone DEFAULT now(),
  org_id uuid NOT NULL,
  CONSTRAINT payout_log_payout_type_check CHECK ((payout_type = ANY (ARRAY['weekly_payroll'::text, 'pay_raise'::text, 'bonus'::text, 'advance'::text, 'advance_repayment'::text, 'adjustment'::text, 'credential_bonus'::text, 'education_bonus'::text, 'promotion_raise'::text, 'performance_bonus'::text, 'holiday_bonus'::text, 'referral_bonus'::text, 'retention_bonus'::text, 'spot_bonus'::text, 'completion_bonus'::text]))),
  CONSTRAINT payout_log_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'cancelled'::text, 'reversed'::text]))),
  CONSTRAINT payout_log_pkey PRIMARY KEY (id)
);

