-- ── registered_users ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.registered_users (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  email text NOT NULL,
  password_hash text NOT NULL,
  name text NOT NULL,
  roles text[] DEFAULT ARRAY['employee'::text],
  is_approved boolean DEFAULT true,
  is_banned boolean DEFAULT false,
  banned_at timestamp with time zone,
  banned_reason text,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  auth_provider text,
  avatar_url text,
  last_sign_in timestamp with time zone,
  default_org_id uuid,
  equipment_self_checkout boolean DEFAULT false NOT NULL,
  worker_classification text DEFAULT 'unclassified'::text NOT NULL,
  CONSTRAINT registered_users_worker_classification_chk CHECK ((worker_classification = ANY (ARRAY['unclassified'::text, 'w2'::text, 'contractor_1099'::text]))),
  CONSTRAINT registered_users_pkey PRIMARY KEY (id),
  CONSTRAINT registered_users_email_key UNIQUE (email)
);

-- ── rewards_catalog ───────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.rewards_catalog (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  name text NOT NULL,
  description text,
  category text NOT NULL,
  xp_cost integer NOT NULL,
  image_url text,
  tier text DEFAULT 'bronze'::text NOT NULL,
  stock_quantity integer DEFAULT '-1'::integer,
  is_active boolean DEFAULT true,
  sort_order integer DEFAULT 0,
  created_at timestamp with time zone DEFAULT now(),
  cash_price numeric(8,2) DEFAULT NULL::numeric,
  CONSTRAINT rewards_catalog_category_check CHECK ((category = ANY (ARRAY['apparel'::text, 'gear'::text, 'gift_cards'::text, 'accessories'::text, 'cash_bonus'::text, 'other'::text]))),
  CONSTRAINT rewards_catalog_tier_check CHECK ((tier = ANY (ARRAY['bronze'::text, 'silver'::text, 'gold'::text, 'platinum'::text, 'diamond'::text]))),
  CONSTRAINT rewards_catalog_pkey PRIMARY KEY (id)
);

-- ── rewards_purchases ─────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.rewards_purchases (
