  status text DEFAULT 'pending'::text NOT NULL,
  fulfilled_by text,
  fulfilled_at timestamp with time zone,
  notes text,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT rewards_purchases_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'fulfilled'::text, 'cancelled'::text]))),
  CONSTRAINT rewards_purchases_pkey PRIMARY KEY (id)
);

