-- ── scheduled_bonuses ─────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.scheduled_bonuses (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  user_email text NOT NULL,
  amount numeric(10,2) NOT NULL,
  bonus_type text DEFAULT 'performance'::text,
  reason text NOT NULL,
  scheduled_date date NOT NULL,
  scheduled_time time without time zone DEFAULT '09:00:00'::time without time zone,
  status text DEFAULT 'scheduled'::text,
  created_by text NOT NULL,
  paid_at timestamp with time zone,
  notes text,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT scheduled_bonuses_amount_check CHECK ((amount > (0)::numeric)),
  CONSTRAINT scheduled_bonuses_bonus_type_check CHECK ((bonus_type = ANY (ARRAY['performance'::text, 'holiday'::text, 'referral'::text, 'retention'::text, 'spot'::text, 'completion'::text, 'other'::text]))),
  CONSTRAINT scheduled_bonuses_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'paid'::text, 'cancelled'::text]))),
  CONSTRAINT scheduled_bonuses_pkey PRIMARY KEY (id)
);

